import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

public abstract class AbstractAtomProvider<T extends Element> implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** A single, thread‑safe Abdera engine instance. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Flag controlling charset autodetection. */
    private boolean autodetectCharset;

    // other methods …

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        if (entityStream == null) {
            throw new IllegalArgumentException("Input stream cannot be null");
        }

        /* Obtain a fresh parser instance for each request.  This guarantees that
         * the parser configuration is applied atomically before parsing begins,
         * eliminating race conditions that could arise when reusing a shared
         * parser across threads. */
        Parser parser = ATOM_ENGINE.getParser();

        /* Configure parser options to mitigate XXE attacks.  The options are
         * applied *before* the parse call, ensuring that entity resolution is
         * disabled regardless of concurrent access. */
        ParserOptions options = parser.getDefaultParserOptions();
        if (options != null) {
            options.setAutodetectCharset(autodetectCharset);
            options.setResolveEntities(false);
        }

        /* Parse the input stream using the configured options.  The overloaded
         * parse method accepts ParserOptions, guaranteeing that the options
         * take effect for this specific parse operation. */
        Document<T> document = parser.parse(entityStream, options);
        return document.getRoot();
    }

    // other methods …
}
