public static File allocateFile(File dir, String name) {
    Objects.requireNonNull(dir, "dir must not be null");
    Objects.requireNonNull(name, "name must not be null");

    // Remove query parameters
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
