    // Resolve and normalize path
    Path targetPath = dir.toPath().resolve(name).normalize();

    // Ensure targetPath is within dir
    if (!targetPath.startsWith(dir.toPath().normalize())) {
        throw new IllegalArgumentException("Attempt to create file outside of target directory: " + name);
    }

    File file = targetPath.toFile();

    // Handle duplicate names
