    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = targetPath.getParent().resolve(prefix + "-" + index++ + suffix).toFile();
    }

    // Create parent directories
