import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Objects;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name} as the base.
     * The method protects against directory‑traversal attacks by normalizing
     * the resolved path and ensuring it stays within {@code dir}. It also
     * guarantees that the parent directories exist.
     *
     * @param dir  the target directory (must exist or be creatable)
     * @param name the desired file name (may contain query parameters)
     * @return a {@link File} instance pointing to the allocated file
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  or if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        // Basic null checks
        Objects.requireNonNull(dir, "Target directory must not be null");
        Objects.requireNonNull(name, "File name must not be null");

        // Strip query parameters (e.g., "?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the target directory
        Path targetPath = dir.toPath().resolve(name).normalize();

        // Ensure the resolved path is still inside the target directory
        Path normalizedDir = dir.toPath().normalize();
        if (!targetPath.startsWith(normalizedDir)) {
            throw new IllegalArgumentException(
                "Attempt to create file outside of target directory: " + name);
        }

        File file = targetPath.toFile();

        // Handle duplicate names by appending "-N" before the extension
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            Path sibling = targetPath.getParent()
                                     .resolve(prefix + "-" + index++ + suffix);
            file = sibling.toFile();
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            try {
                if (!parent.mkdirs() && !parent.isDirectory()) {
                    throw new IOException("Failed to create parent directories for " + file);
                }
            } catch (IOException e) {
                throw new IllegalStateException("Could not create directories for " + file, e);
            }
        }

        return file;
    }

    // other methods
}
