public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // other methods ...

    /**
     * Validates a media type token (major or subtype). According to RFC 7230,
     * a token consists of one or more tchar characters. The tchar set includes
     * alphanumerics and a small set of punctuation marks. The wildcard "*" is
     * also allowed for media type wildcards.
     *
     * @param str the token to validate
     * @return {@code true} if the token is valid, {@code false} otherwise
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the single character wildcard "*"
        if ("*".equals(str)) {
            return true;
        }
        // Reject any string that contains characters outside the RFC‑defined tchar set
        return TOKEN_PATTERN.matcher(str).matches();
    }

