public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path by ensuring it starts with a single leading slash
     * and removing any additional leading slashes. If the input is {@code null},
     * {@code null} is returned. An empty path is normalized to {@code "/"}.
     *
     * @param path the original path string
     * @return the normalized path
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Count leading slashes
        int leadingSlashCount = 0;
        while (leadingSlashCount < path.length()
                && path.charAt(leadingSlashCount) == '/') {
            leadingSlashCount++;
        }

        // Build the normalized path
        StringBuilder sb = new StringBuilder();

        // Always start with a single slash
        sb.append('/');

        // Append the remainder of the path after all leading slashes
        if (leadingSlashCount < path.length()) {
            sb.append(path.substring(leadingSlashCount));
        }

        return sb.toString();
    }

