     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical (real) path of the target directory once.
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject empty names – they would resolve to the target directory itself.
            if (entryName == null || entryName.trim().isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Reject absolute paths (both Unix and Windows styles).
            if (Paths.get(entryName).isAbsolute()) {
                throw new IOException("archive entry uses an absolute path: " + entryName);
            }

            // Reject any path component that is ".." or contains backslashes
            // (Windows style separators) which could lead to traversal.
