            Path entryPath = targetPath.resolve(entryName).normalize();

            // Ensure the resolved path is still within the target directory.
            if (!entryPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
