            int toReadFromStream = (int) Math.min(buf.capacity(), remaining);

            // Read from the underlying stream. We explicitly read into the buffer's backing array
            // to avoid allocating temporary arrays on each call.
            int l = in.read(buf.array(), 0, toReadFromStream);
