    /* --------------------------------------------------------------------- */
    /*  Whitelist of safe component types                                   */
    /* --------------------------------------------------------------------- */

    /** Maximum number of elements allowed in a deserialized array. */
    private static final int MAX_ARRAY_LENGTH = 10_000;

    /** Set of component classes that are considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES;

    static {
        Set<Class<?>> tmp = new HashSet<>();
        // Primitive wrappers
        tmp.add(Boolean.class);
        tmp.add(Byte.class);
        tmp.add(Character.class);
        tmp.add(Short.class);
        tmp.add(Integer.class);
        tmp.add(Long.class);
        tmp.add(Float.class);
        tmp.add(Double.class);
        // Common immutable types
        tmp.add(String.class);
        tmp.add(java.math.BigDecimal.class);
        tmp.add(java.math.BigInteger.class);
        tmp.add(java.util.Date.class);
        tmp.add(java.time.LocalDate.class);
        tmp.add(java.time.LocalDateTime.class);
        tmp.add(java.time.OffsetDateTime.class);
        tmp.add(java.time.ZonedDateTime.class);
        // Add more types as required by the application
        SAFE_COMPONENT_TYPES = Collections.unmodifiableSet(tmp);
    }

    /* --------------------------------------------------------------------- */
    /*  Deserialization logic                                               */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle JSON string literal → byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        Class<?> componentClass;
        Type componentType;

        // Resolve component type for generic array types
        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType paramType = (ParameterizedType) contextType;
                    Type rawType = paramType.getRawType();
                    Type actualType = null;

                    if (rawType instanceof Class) {
                        TypeVariable<?>[] typeParams = ((Class<?>) rawType).getTypeParameters();
                        for (int i = 0; i < typeParams.length; ++i) {
                            if (typeParams[i].getName().equals(typeVar.getName())) {
                                actualType = paramType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = (actualType instanceof Class)
                            ? (Class<?>) actualType
                            : Object.class;
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else { // Non-generic array
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        // -----------------------------------------------------------------
        // Validation: enforce whitelist and size limits
        // -----------------------------------------------------------------

        if (!SAFE_COMPONENT_TYPES.contains(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type [" + componentClass.getName()
                            + "] is not allowed.");
        }

        // Parse the JSON array into a temporary JSONArray
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        // Enforce maximum array length
        if (array.size() > MAX_ARRAY_LENGTH) {
            throw new IllegalArgumentException(
                    "Array size [" + array.size() + "] exceeds the maximum allowed ["
                            + MAX_ARRAY_LENGTH + "].");
        }

        // Convert JSONArray to a typed array
        return (T) toObjectArray(parser, componentClass, array);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods (unchanged)                                           */
    /* --------------------------------------------------------------------- */

    // Existing helper methods like toObjectArray() remain unchanged.
}
